<template>
  <div>
    <el-tabs v-model="activeName">
      <el-tab-pane label="参数配置" name="1"></el-tab-pane>
      <el-tab-pane label="证书管理" name="2"></el-tab-pane>
      <el-tab-pane label="连接状态" name="3"></el-tab-pane>
    </el-tabs>
    <div class="d-center">
      <el-form
        :model="addform"
        :rules="rules"
        ref="addform"
        label-width="130px"
        class="demo-ruleForm mt-30"
        size="small"
        style="width: 40%"
        :validate-on-rule-change="false"
      >
        <template v-if="activeName == '1'">
          <el-form-item label="启用:">
            <el-select v-model="addform.status">
              <el-option label="是" :value="1"></el-option>
              <el-option label="否" :value="2"></el-option>
            </el-select>
          </el-form-item>
          <el-form-item label="设备类型:" prop="dev_type">
            <el-select v-model="addform.config_info.dev_type">
              <el-option value="tun"></el-option>
              <el-option value="tap"></el-option>
            </el-select>
          </el-form-item>
          <el-form-item label="通道协议:" prop="proto">
            <el-select v-model="addform.config_info.proto">
              <el-option value="tcp"></el-option>
              <el-option value="udp"></el-option>
            </el-select>
          </el-form-item>
          <el-form-item label="服务端口:" prop="port">
            <el-input-number v-model="addform.config_info.port" />
          </el-form-item>
          <el-form-item label="服务器地址:" prop="address">
            <el-input v-model="addform.config_info.address" />
          </el-form-item>
          <el-form-item label="用户名:" prop="user">
            <el-input v-model="addform.config_info.user" />
          </el-form-item>
          <el-form-item label="密码:" prop="pwd">
            <el-input
              v-model="addform.config_info.pwd"
              type="password"
              autocomplete="off"
              show-password
            />
          </el-form-item>
          <el-form-item label="最大传输单位:" prop="mtu">
            <el-input-number v-model="addform.config_info.mtu" />
          </el-form-item>
          <el-form-item label="加密算法:" prop="cipher">
            <el-select v-model="addform.config_info.cipher">
              <el-option
                :value="item"
                v-for="item in algorithms"
                :key="item"
              ></el-option>
            </el-select>
          </el-form-item>
          <el-form-item label="LZO压缩:">
            <el-checkbox v-model="addform.config_info.comp_lzo"
              >开启</el-checkbox
            >
          </el-form-item>
          <el-form-item label="CA证书:" prop="ca">
            <el-input v-model="addform.config_info.ca" type="textarea" />
          </el-form-item>
        </template>
        <template v-else-if="activeName == '2'">
          <el-form-item label="客户端证书:" prop="cert">
            <el-input v-model="addform.config_info.cert" type="textarea" />
          </el-form-item>
          <el-form-item label="客户端私钥:" prop="key">
            <el-input v-model="addform.config_info.key" type="textarea" />
          </el-form-item>
        </template>
        <template v-else>
          <el-form-item label="状态:">
            {{ addform.is_connected == 1 ? "已连接" : "断开" }}
          </el-form-item>
          <el-form-item label="本地IPv4:">
            {{ addform.local_ipv4 || "未知" }}
          </el-form-item>
          <el-form-item label="子网掩码:">
            {{ addform.local_mask || "未知" }}
          </el-form-item>
        </template>
        <el-form-item v-if="activeName !== '3'">
          <el-button
            type="primary"
            @click="submitForm('addform')"
            :loading="loading"
          >
            保存
          </el-button>
        </el-form-item>
        <el-form-item v-else>
          <el-button type="primary" @click="getData" :loading="loading">
            刷新
          </el-button>
        </el-form-item>
      </el-form>
    </div>
  </div>
</template>

<script>
export default {
  data() {
    return {
      addform: {},
      algorithms: [
        "BF-CBC",
        "BF-CFB",
        "BF-OFB",
        "DES-CFB",
        "DES-CBC",
        "RC2-CBC",
        "RC2-CFB",
        "RC2-OFB",
        "DES-EDE-CBC",
        "DES-EDE3-CBC",
        "DES-OFB",
        "DES-EDE-CFB",
        "DES-EDE3-CFB",
        "DES-EDE-OFB",
        "DES-EDE3-OFB",
        "DESX-CBC",
        "RC2-40-CBC",
        "CAST5-CBC",
        "CAST5-CFB",
        "CAST5-OFB",
        "RC2-64-CBC",
        "AES-128-CBC",
        "AES-128-OFB",
        "AES-128-CFB",
        "AES-192-CBC",
        "AES-192-OFB",
        "AES-192-CFB",
        "AES-256-CBC",
        "AES-256-OFB",
        "AES-256-CFB",
        "AES-128-CFB1",
        "AES-192-CFB1",
        "AES-256-CFB1",
        "AES-128-CFB8",
        "AES-192-CFB8",
        "AES-256-CFB8",
        "AES-256-GCM",
        "DES-CFB1",
        "DES-CFB8",
        "DES-EDE3-CFB1",
        "DES-EDE3-CFB8",
        "SEED-CBC",
        "SEED-OFB",
        "SEED-CFB",
        "none",
      ],
      activeName: "1",
      rules: {},
    };
  },
  created() {
    this.getData();
  },
  methods: {
    async getData() {
      try {
        const res = await this.$api.get("/net/getVpn", {
          params: {
            protocol_type: 3,
          },
        });
        let data = res.data.data;
        if (data) {
          // this.addform = { ...data };
          if (data.config_info) {
            this.addform = data;
          } else {
            this.addform = { ...data, config_info: { port: 1400 } };
          }
        } else {
          this.addform = {
            config_info: { port: 1400 },
          };
          this.$nextTick(() => {
            this.$refs.addform.clearValidate();
          });
        }
        return true;
      } catch (error) {
        console.error("获取失败:", error);
        return false;
      }
    },
    async submitForm(formName) {
      let data = {
        protocol_type: 3,
        config_info: this.addform.config_info,
        id: this.addform.id,
        status: this.addform.status,
      };
      try {
        const valid = await this.$refs[formName].validate();
        if (!valid) return;
        this.loading = true;
        await this.$api.post("/net/updateVpn", data);
        this.$message.success("操作成功");
        this.getData();
      } catch (error) {
        console.error("启动检测失败:", error);
      } finally {
        this.loading = false;
      }
    },
  },
};
</script>

<style lang="scss" scoped></style>
